  outline-offset: 2px;
}
:where([data-lace-part="lightbox"]) {
  background: transparent;
  border: 0;
  max-height: 100dvh;
  max-width: 100vw;
  padding: 0;
}
:where([data-lace-part="lightbox"])::backdrop {
  background: rgb(0 0 0 / 0.85);
}
:where([data-lace-part="lightbox-media"]) {
  display: block;
  height: auto;
  max-height: 100dvh;
  max-width: 100vw;
  object-fit: contain;
  width: auto;
}
:where([data-lace-part="lightbox-close"]) {
  background: #faf9f6;
  border: 0;
  border-radius: 999px;
  color: #1c2524;
  cursor: pointer;
  font: inherit;
  padding: 0.5rem 1rem;
  position: fixed;
  right: 1rem;
  top: 1rem;
}

/* Navigation: a vertical list on narrow screens, a row with dropdowns from 48rem. */
:where([data-lace-block="navigation"], .site-nav) ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
:where([data-lace-block="navigation"]) [data-lace-part="list"],
:where(.site-nav) > ul {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
:where([data-lace-block="navigation"]) a,
:where([data-lace-block="navigation"]) summary {
  overflow-wrap: anywhere;
}
:where([data-lace-block="navigation"]) [data-lace-part="toggle"] {
  cursor: pointer;
}
:where([data-lace-block="navigation"]) [data-lace-part="children"] {
  display: grid;
  gap: 0.25rem;
  margin-block-start: 0.5rem;
  padding-inline-start: 1rem;
}
:where([data-lace-block="navigation"]) [aria-current="page"] {
  font-weight: 700;
}
.site-header > nav {
  flex-basis: 100%;
}
@media (min-width: 48rem) {
  :where([data-lace-block="navigation"]) [data-lace-part="list"],
  :where(.site-nav) > ul {
    flex-flow: row wrap;
    gap: 0.5rem 1.5rem;
  }
  :where([data-lace-block="navigation"]) [data-lace-part="submenu"] {
    position: relative;
  }
  :where([data-lace-block="navigation"]) [data-lace-part="children"] {
    background: Canvas;
    border: 1px solid;
    inset-block-start: 100%;
    inset-inline-start: 0;
    min-width: 12rem;
    padding: 0.75rem;
    position: absolute;
    z-index: 1;
  }
  .site-header > nav {
    flex-basis: auto;
    margin-inline-start: auto;
  }
}

/* Only resolved anchors get a navigation affordance; unavailable labels remain plain text. */
.link {
  margin-block: 1rem;
}
.link[data-lace-appearance="button"] [data-lace-part="link"] {
  display: inline-block;
  padding: 0.65rem 1rem;
  border: 1px solid currentColor;
  border-radius: 0.35rem;
  text-decoration: none;
}
.link[data-lace-appearance="text"] [data-lace-part="link"] {
  text-decoration: underline;
}
.link [data-lace-part="link"]:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
}
